describe('Data Table Responsive Stacking', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport('iphone-x');
  });

  it('should stack table columns vertically on small screens', () => {
    cy.get('[data-testid="data-table"]').should('exist');

    cy.get('[data-testid="data-table"] thead').should('not.be.visible');

    cy.get('[data-testid="data-table"] tbody tr').each(($row) => {
      cy.wrap($row).should('have.css', 'display', 'block');
    });

    cy.get('[data-testid="data-table"] tbody td').each(($cell) => {
      cy.wrap($cell).should('have.css', 'display', 'block');
      cy.wrap($cell).should('have.css', 'width', '100%');
    });

    cy.get('[data-testid="data-table"] tbody td').each(($cell) => {
      cy.wrap($cell).should('have.attr', 'data-label');
    });
  });

  it('should display data labels before cell content on mobile', () => {
    cy.get('[data-testid="data-table"] tbody td').first().then(($cell) => {
      const label = $cell.attr('data-label');
      cy.wrap($cell).should('contain', label);
    });

    cy.get('[data-testid="data-table"] tbody td').each(($cell) => {
      const label = $cell.attr('data-label');
      cy.wrap($cell).should('have.attr', 'data-label', label);
      cy.wrap($cell).invoke('css', 'content').should('include', label);
    });
  });

  it('should maintain proper spacing between stacked rows on small screens', () => {
    cy.get('[data-testid="data-table"] tbody tr').each(($row) => {
      cy.wrap($row).should('have.css', 'margin-bottom');
      cy.wrap($row).should('have.css', 'border-bottom');
    });

    cy.get('[data-testid="data-table"] tbody tr').first().then(($firstRow) => {
      const marginBottom = $firstRow.css('margin-bottom');
      cy.get('[data-testid="data-table"] tbody tr').eq(1).should('have.css', 'margin-bottom', marginBottom);
    });
  });

  it('should revert to table layout on larger screens', () => {
    cy.viewport('macbook-15');

    cy.get('[data-testid="data-table"] thead').should('be.visible');

    cy.get('[data-testid="data-table"] tbody tr').each(($row) => {
      cy.wrap($row).should('have.css', 'display', 'table-row');
    });

    cy.get('[data-testid="data-table"] tbody td').each(($cell) => {
      cy.wrap($cell).should('have.css', 'display', 'table-cell');
    });
  });

  it('should handle empty table gracefully on mobile', () => {
    cy.get('[data-testid="data-table"]').then(($table) => {
      const rowCount = $table.find('tbody tr').length;

      if (rowCount === 0) {
        cy.get('[data-testid="empty-state"]').should('be.visible');
        cy.get('[data-testid="empty-state"]').should('contain', 'No data available');
      }
    });
  });

  it('should handle table with many columns on mobile without horizontal scroll', () => {
    cy.get('[data-testid="data-table"]').should('have.css', 'overflow-x', 'visible');

    cy.get('[data-testid="data-table"] tbody td').each(($cell) => {
      cy.wrap($cell).should('have.css', 'word-wrap', 'break-word');
    });

    cy.get('[data-testid="data-table"]').invoke('width').then((tableWidth) => {
      cy.viewport('iphone-x').then(() => {
        cy.get('[data-testid="data-table"]').invoke('width').should('be.lte', tableWidth);
      });
    });
  });

  it('should maintain data integrity when stacking', () => {
    const expectedData = [
      { name: 'John Doe', email: 'john@example.com', status: 'Active' },
      { name: 'Jane Smith', email: 'jane@example.com', status: 'Inactive' }
    ];

    cy.get('[data-testid="data-table"] tbody tr').each(($row, index) => {
      cy.wrap($row).find('td').each(($cell, cellIndex) => {
        const label = $cell.attr('data-label');
        const cellText = $cell.text().trim();

        if (label && expectedData[index]) {
          const expectedValue = expectedData[index][label.toLowerCase()];
          if (expectedValue) {
            cy.wrap($cell).should('contain', expectedValue);
          }
        }
      });
    });
  });

  it('should handle responsive table with interactive elements', () => {
    cy.get('[data-testid="data-table"] tbody td button').should('be.visible');

    cy.get('[data-testid="data-table"] tbody td button').first().should('have.css', 'width', '100%');

    cy.get('[data-testid="data-table"] tbody td button').first().click();
    cy.get('[data-testid="action-modal"]').should('be.visible');
  });
});
